import{_ as l,C as r,c as n,o as s,aa as i,G as a}from"./chunks/framework.Cn7WEiMX.js";const R=JSON.parse('{"title":"使用自定义方块渲染器","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/Dynmap/mod-support/using-custom-block-renderers.md","filePath":"wiki/Dynmap/mod-support/using-custom-block-renderers.md"}'),t={name:"wiki/Dynmap/mod-support/using-custom-block-renderers.md"};function p(m,e,c,h,u,C){const d=r("NolebaseGitContributors"),o=r("NolebaseGitChangelog");return s(),n("div",null,[e[0]||(e[0]=i('<h1 id="使用自定义方块渲染器" tabindex="-1">使用自定义方块渲染器 <a class="header-anchor" href="#使用自定义方块渲染器" aria-label="Permalink to &quot;使用自定义方块渲染器&quot;">​</a></h1> <p>部分方块的渲染逻辑更加复杂，超出了简单的方块 ID 与元数据绑定的范围。这包括会受到相邻方块影响的方块（红石线、栅栏、墙壁、玻璃板以及楼梯），以及那些依赖于 TileEntity 数据或其他信息（头颅、<a href="https://www.mcmod.cn/class/6.html" target="_blank" rel="noreferrer">铁路工艺</a>的方块、<a href="https://www.mcmod.cn/class/129.html" target="_blank" rel="noreferrer">Immibis 的小方块</a>）</p> <p>若要让某个模型使用自定义方块渲染器，需要设置 <code>customblock</code> 参数。它的基础属性如下：</p> <ul><li><code>id</code> - 使用此模型的方块 ID。需要指定至少一个 <code>id</code> 属性，但数量不限——允许同一模型用在多个方块。见“<a href="./texture-definition-files#方块-id-数字">方块 ID 数字</a>”了解如何指定方块 ID 数字的详情。</li> <li><code>data</code> - 对模型应用的方块增加匹配数据值的要求。默认值 <code>data=*</code> 表示匹配所有对应 <code>id</code> 属性下带有任何数据值的方块。否则，只匹配一或多个 <code>data=数字</code> 元数据的方块。</li> <li><code>scale</code> - 自定义方块渲染器的完整类名。必填项。</li></ul> <p><code>customblock</code> 设置可能会随使用的渲染器而包含额外属性。</p> <p>自定义方块渲染器总是会生成补丁定义序列（对于纹理应用位置的指示）。对应补丁的序号由自定义方块渲染器决定。<a href="./texture-definition-files">纹理定义文件</a>提供的纹理引用需要在对应 <code>block</code> 部分配置中指定 <code>patch&lt;数字&gt;</code> 属性。</p> <h2 id="现有的自定义方块渲染器" tabindex="-1">现有的自定义方块渲染器 <a class="header-anchor" href="#现有的自定义方块渲染器" aria-label="Permalink to &quot;现有的自定义方块渲染器&quot;">​</a></h2> <p>Dynmap 默认提供了如下自定义方块渲染器，在合适的时候可以用在新的自定义方块上。</p> <ul><li>Class org.dynmap.hdmap.renderer.BoxRenderer - 立方体模型渲染器</li> <li>Class org.dynmap.hdmap.renderer.CTMVertTextureRenderer</li> <li>Class org.dynmap.hdmap.renderer.FenceWallBlockRenderer - 栅栏与墙壁使用的渲染器</li> <li>Class org.dynmap.hdmap.renderer.FrameRenderer</li> <li>Class org.dynmap.hdmap.renderer.ImmibisMicroRenderer</li> <li>Class org.dynmap.hdmap.renderer.PaneRenderer - 玻璃板与铁栅栏使用的渲染器</li> <li>Class org.dynmap.hdmap.renderer.RailCraftSlabBlockRenderer</li> <li>Class org.dynmap.hdmap.renderer.RailCraftTrackRenderer</li> <li>Class org.dynmap.hdmap.renderer.RedstoneWireRenderer - 红石导线使用的渲染器</li> <li>Class org.dynmap.hdmap.renderer.RotatedBoxRenderer</li> <li>Class org.dynmap.hdmap.renderer.RotatedPatchRenderer</li> <li>Class org.dynmap.hdmap.renderer.RPMicroRenderer</li> <li>Class org.dynmap.hdmap.renderer.RPRotatedBoxRenderer</li> <li>Class org.dynmap.hdmap.renderer.RPSupportFrameRenderer</li> <li>Class org.dynmap.hdmap.renderer.SkullRenderer - the renderer used for vanilla skulls/heads</li> <li>Class org.dynmap.hdmap.renderer.StairBlockRenderer - the renderer used for standard stairs blocks</li> <li>Class org.dynmap.hdmap.renderer.TFCLooseRockRenderer</li> <li>Class org.dynmap.hdmap.renderer.TFCSupportRenderer</li> <li>Class org.dynmap.hdmap.renderer.TFCWoodRenderer</li> <li>Class org.dynmap.hdmap.renderer.ThaumFurnaceRenderer</li></ul> ',18)),a(d),a(o)])}const _=l(t,[["render",p]]);export{R as __pageData,_ as default};
